package main import "fmt" func main() { // 1. 普通数组声明（显式指定长度） var arr1 [3]int = [3]int{1, 2, 3} // 2. 切片声明（中括号里为空） var slice1 []int = []int{1, 2, 3} // 3. 使用 ... 自动推断长度的数组 // 编译器数了一下后面有4个元素，自动把它变成 [4]int 类型 arr2 := [...]int{10, 20, 30, 40} fmt.Printf("arr1 类型: %T (长度写死)
", arr1) // [3]int fmt.Printf("slice1 类型: %T (切片)
", slice1) // []int fmt.Printf("arr2 类型: %T (自动推断)
", arr2) // [4]int }

#include <stdio.h> // 定义常量宏 #define PI 3.14159 #define MAX_SIZE 100 // 定义函数宏 #define SQUARE(x) ((x) * (x)) #define MIN(a, b) ((a) < (b) ? (a) : (b)) // 调试宏 #define DEBUG #ifdef DEBUG #define LOG(msg) printf("DEBUG: %s
", msg) #else #define LOG(msg) #endif int main() { printf("PI: %f
", PI); printf("Square of 5: %d
", SQUARE(5)); printf("Min of 3 and 7: %d
", MIN(3, 7)); LOG("This is a debug message"); return 0; }
